query.const:
query ListItems($projectId: ID!, $first: Int!, $cursor: String) {
  node(id: $projectId) {
    ... on ProjectV2 {
      items(first: $first, after: $cursor, archivedStates: [NOT_ARCHIVED]) {
        pageInfo { hasNextPage endCursor }
        nodes {
          id
          content {
            __typename
            ... on DraftIssue { title body }
            ... on Issue { title body }
            ... on PullRequest { title }
          }
        }
      }
    }
  }
}
